Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

(* [comment removed for export] *)
Ltac shbr_mid :=
  lazymatch goal with
  | |- evt ?segs ?Q (MS ?R ?F (if ?c then Z_to_bv 64 ?SLOW else Z_to_bv 64 ?FAST) ?fc ?rv ?m ?ro) =>
      let b := shbyte_of c in
      lazymatch goal with
      | K : shk m b ?X |- _ =>
          let OK := fresh "SHOK" in
          first [
            match goal with
            | ACC : acc asegs m ?a ?n, AL : ?a mod 16 = 0, P0 : 0 < ?a |- _ =>
                assert (OK : bv_unsigned b = 0)
                  by (clear - ACC AL P0 K;
                      apply (sh_ok_8 b (X - X mod 8)); [| Z.div_mod_to_equations; lia];
                      refine (shk_ok m a n (X - X mod 8) 8 b ACC _ _ _ _ _ _);
                      [ unfold shk in K |- *; replace (shad (X - X mod 8)) with (shad X) by (unfold shad; Z.div_mod_to_equations; lia); exact K
                      | Z.div_mod_to_equations; lia | Z.div_mod_to_equations; lia | lia | Z.div_mod_to_equations; lia | Z.div_mod_to_equations; lia ])
            end
          | fail 1 "shbr_mid: cannot prove the granule addressable:" X ];
          rewrite ?(sxb_small b) by lia; brF; rewrite ?OK; clear K OK
      end
  end.
Ltac awalk1 ::=
  lazymatch goal with
  | |- evt _ _ (MS _ _ (if _ then _ else _) _ _ _ _) => first [ shbr | shbr0 | shbr_inv | shbr_x3 | shbr_mid | br ]
  | |- evt _ _ (MS _ _ (Z_to_bv 64 _) _ _ _ _) => first [ shload; lstep; clear_shl | special_step | frame_step | lstep; try sb_fix; try fix_land32; shnorm ]
  end.

